pub fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Assume `a.len() == b.len()` as stated.
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x < y)
        .collect()
}